package com.lifeorganizer;
import javafx.geometry.*;import javafx.scene.control.*;import javafx.scene.layout.*;import java.sql.*;
public class ReminderCenterView extends VBox {
 private final int userId;private final TextArea list=new TextArea();
 public ReminderCenterView(int id){userId=id;setPadding(new Insets(20));setSpacing(12);Label h=new Label("Reminders, Snooze & Completion");h.setStyle("-fx-font-size:25px;-fx-font-weight:bold;");Button refresh=new Button("Refresh"),clear=new Button("Reset selected reminder state");refresh.setOnAction(e->load());clear.setOnAction(e->reset());list.setEditable(false);list.setPrefRowCount(22);getChildren().addAll(h,new Label("Reminders are checked while the application is running. Snoozed items reappear after their snooze time; completed items are suppressed for the day."),new HBox(8,refresh,clear),list);load();}
 private void load(){StringBuilder b=new StringBuilder("UPCOMING EVENTS\n");try(Connection c=Db.connect()){
  String[][] q={{"SELECT CONCAT('Medicine: ',medicine_name,' | time ',reminder_time),CONCAT('medicine:',medicine_id,':',CURDATE()) FROM medicines WHERE user_id=? ORDER BY reminder_time LIMIT 50"},{"SELECT CONCAT('Event: ',event_title,' | ',event_date,' ',COALESCE(event_time,'')),CONCAT('event:',event_id,':',event_date) FROM calendar_events WHERE user_id=? AND event_date>=CURDATE() ORDER BY event_date,event_time LIMIT 50"},{"SELECT CONCAT('Task: ',task_name,' | due ',deadline,' | ',status),CONCAT('task:',task_id,':',deadline) FROM tasks WHERE user_id=? AND status<>'Completed' AND deadline>=CURDATE() ORDER BY deadline LIMIT 50"},{"SELECT CONCAT('Bill: ',bill_name,' | due ',due_date,' | ',payment_status),CONCAT('bill:',bill_id,':',due_date) FROM bills WHERE user_id=? AND payment_status='Unpaid' AND due_date>=CURDATE() ORDER BY due_date LIMIT 50"}};
  for(String[] query:q){try(PreparedStatement p=c.prepareStatement(query[0])){p.setInt(1,userId);try(ResultSet r=p.executeQuery()){while(r.next())b.append(r.getString(1)).append("\nReminder key: ").append(r.getString(2)).append("\n\n");}}}
  try(PreparedStatement p=c.prepareStatement("SELECT reminder_key,action_type,snooze_until,updated_at FROM reminder_actions WHERE user_id=? ORDER BY updated_at DESC LIMIT 50")){p.setInt(1,userId);try(ResultSet r=p.executeQuery()){b.append("\nSNOOZED / COMPLETED HISTORY\n");while(r.next())b.append(r.getString(1)).append(" | ").append(r.getString(2)).append(" | ").append(r.getTimestamp(3)).append("\n");}}
 }catch(Exception e){b.append("\nReminder data unavailable: ").append(e.getMessage()).append("\nRun database/upgrade_all.sql.");}list.setText(b.toString());}
 private void reset(){TextInputDialog d=new TextInputDialog();d.setTitle("Reset reminder");d.setHeaderText("Enter the exact Reminder key shown above");d.setContentText("Reminder key:");d.showAndWait().ifPresent(key->{try(Connection c=Db.connect();PreparedStatement p=c.prepareStatement("DELETE FROM reminder_actions WHERE user_id=? AND reminder_key=?")){p.setInt(1,userId);p.setString(2,key.trim());p.executeUpdate();load();}catch(Exception e){new Alert(Alert.AlertType.ERROR,e.getMessage()).showAndWait();}});}
}
